window.COLLECTION = [{"number": "0001", "file": "0001 - Capella Bangkok - River Suite Premier - bedroom with king bed and river window daybed.jpg", "resort": "Capella Bangkok", "space": "River Suite Premier", "description": "The bedroom is arranged for the river, with a king bed dressed in plain white Egyptian cotton and a low upholstered daybed set along the glazing at its foot, so the view is taken lying down as much as sitting up. Walls and joinery are blonde timber with a fabric shaded wall sconce beside the bedhead, and oatmeal linen Roman blinds soften the black framed floor to ceiling windows and balcony sliders. A black arc floor lamp marks the window corner. To recreate it, keep the palette to warm white, sand and pale oak, furniture low and horizontal, and textiles unpatterned.", "src": "images/Capella Bangkok/0001 - Capella Bangkok - River Suite Premier - bedroom with king bed and river window daybed.jpg", "source": "https://capellahotels.com/en/capella-bangkok/accommodation/river-premier-suite", "dimensions": "1296x723", "size": 159483}, {"number": "0002", "file": "0002 - Capella Bangkok - River Suite Premier - corner living room with sofa and barrel chairs.jpg", "resort": "Capella Bangkok", "space": "River Suite Premier", "description": "The separate living room wraps two walls of glass around a corner sofa in oatmeal weave with cushions in sage green and taupe. Two barrel back armchairs in pale leather on dark timber legs face the river, paired with a dark round side table carrying an oversized drum shaded lamp in cream silk on a faceted bronze base. A dark stained desk or console repeats the lamp at smaller scale. Pale carpet, linen Roman blinds and blonde panelling keep the room light. Recreation notes: overscale one lamp, keep upholstery plain, and let green cushions be the only colour accent.", "src": "images/Capella Bangkok/0002 - Capella Bangkok - River Suite Premier - corner living room with sofa and barrel chairs.jpg", "source": "https://capellahotels.com/en/capella-bangkok/accommodation/river-premier-suite", "dimensions": "1296x723", "size": 214806}, {"number": "0005", "file": "0005 - Capella Bangkok - Private Villa - living room looking through to bedroom.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "From the living area, sliding pocket doors open to the bedroom in one enfilade. Foreground pieces include a dark timber display cabinet with blue and white porcelain jars, art books and a sculptural knot object, a tall floor lamp with a cream drum shade, and a marble topped round table. The bedroom has a king bed in white linen, a striped upholstered bench at its foot, and a geometric gridded fabric panel behind the bedhead flanked by mirrored niches and pendant shades. A dressing area with robes and a stool is visible at right. Keep joinery dark against pale walls and repeat grid patterns quietly.", "src": "images/Capella Bangkok/0005 - Capella Bangkok - Private Villa - living room looking through to bedroom.jpg", "source": "https://capellahotels.com/en/capella-bangkok/accommodation/villa", "dimensions": "1296x723", "size": 289259}, {"number": "0006", "file": "0006 - Capella Bangkok - Private Villa - dining room with marble table and shell pendant.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "The combined living and dining room is anchored by an oval marble dining table with cream leather barrel chairs on dark timber frames, lit by a pair of sculptural hammered metal shell pendants. Behind the sofa, a long dark timber console carries a bonsai and an art book, facing a media wall with open shelving and ceramics. Whitewashed boarded ceilings, a ceiling fan, pale oak floors and full height linen curtains frame folding doors to the garden and plunge pool. Recreation notes: one statement pendant group, low horizontal consoles, and indoor planting at architectural scale, including the large potted palm by the doors.", "src": "images/Capella Bangkok/0006 - Capella Bangkok - Private Villa - dining room with marble table and shell pendant.jpg", "source": "https://capellahotels.com/en/capella-bangkok/private-villa", "dimensions": "1920x1282", "size": 309966}, {"number": "0007", "file": "0007 - Capella Bangkok - Private Villa - bedroom with striped chaises and pool doors.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "The villa bedroom keeps furniture low and textile led, with two striped chaise longues in beige and brown weave angled towards the garden, small round black side tables between them, and the king bed in plain white in the foreground. Full width sliding doors open to the plunge pool, sun loungers and lawn, while the inner wall is lined with woven grasscloth panels in a pale sand tone that catch raking sunlight. A white ceiling fan, taupe curtains and a muted flatweave rug finish the room. Recreate with natural fibre wallcovering, striped upholstery as the only pattern, and nothing above waist height.", "src": "images/Capella Bangkok/0007 - Capella Bangkok - Private Villa - bedroom with striped chaises and pool doors.jpg", "source": "https://capellahotels.com/en/capella-bangkok/private-villa", "dimensions": "1280x853", "size": 107422}, {"number": "0011", "file": "0011 - Capella Bangkok - Tea Lounge - rattan armchairs and lattice screens by the lily pond.jpg", "resort": "Capella Bangkok", "space": "Tea Lounge", "description": "The signature Tea Lounge view pairs two woven rattan armchairs with rolled spiral arms and sage cushions against low dark timber tables and upholstered stools, arranged symmetrically on a patterned carpet over polished stone. Behind them, full height windows look onto the lily pond, divided by dark timber lattice screens in a Thai diamond fretwork, with oversized black ceramic planters holding tall palms at each bay. Arched floor lamps with pink silk shades and a coffered ceiling clad in silk complete the room. This is the clearest statement of the hotel lobby look. [below 1200px - best available]", "src": "images/Capella Bangkok/0011 - Capella Bangkok - Tea Lounge - rattan armchairs and lattice screens by the lily pond.jpg", "source": "https://capellahotels.com/en/capella-bangkok/dining", "dimensions": "968x646", "size": 162644}, {"number": "0012", "file": "0012 - Capella Bangkok - Tea Lounge - lobby lounge sofas and Ming style chairs.jpg", "resort": "Capella Bangkok", "space": "Tea Lounge", "description": "This angle of the lobby Tea Lounge shows the deeper seating groups: cream sofas and striped upholstered armchairs around a dark timber coffee table, plus Chinese inspired dark wood armchairs with stone top tables in honey onyx in the foreground. A black lacquer side table with a floral arrangement, drum shaded floor lamps and a display shelf holding a bronze horse sculpture and lacquer boxes add the collected, residential layer. Bronze tinted mirror panels and diamond fretwork screens line the walls, and the lily pond runs outside the glazing. Palette is cream, charcoal, bronze and stone throughout.", "src": "images/Capella Bangkok/0012 - Capella Bangkok - Tea Lounge - lobby lounge sofas and Ming style chairs.jpg", "source": "https://bradajohnson.net/2023/12/16/oltre-review-one-day-in-bangkok-two-worlds-apart/", "dimensions": "2560x1707", "size": 729305}, {"number": "0014", "file": "0014 - Capella Bangkok - Tea Lounge - window armchairs overlooking the lily pond.jpg", "resort": "Capella Bangkok", "space": "Tea Lounge", "description": "Along the Tea Lounge windows, low taupe armchairs with loose cushions are grouped in pairs around small round tables with white cloths, facing the lily pond and the low rise buildings across it. A dark fretwork screen divides the seating from the passage, and a flatweave carpet in mottled grey and cream unifies the groups. Daylight does most of the work, with one shaded lamp for evening. To recreate the feel, set every seat towards water or garden, keep chair backs low so sightlines stay open, and use upholstery in a single warm greige family with cushions a shade darker.", "src": "images/Capella Bangkok/0014 - Capella Bangkok - Tea Lounge - window armchairs overlooking the lily pond.jpg", "source": "https://suiteverdict.com/en/thailand/bangkok/capella-bangkok-verdict", "dimensions": "2560x1707", "size": 731213}, {"number": "0016", "file": "0016 - Capella Bangkok - Phra Nakhon - conservatory dining room with skylight and banquettes.jpg", "resort": "Capella Bangkok", "space": "Phra Nakhon", "description": "Inside Phra Nakhon, the conservatory dining room runs between glass walls under a coffered ceiling with a central skylight screened by woven cane panels. A long grey upholstered banquette with botanical print cushions faces cane backed chairs with dark timber frames at square marble tables set with green glassware and brass cutlery. Herringbone timber floors, a woven screen divider and a large floral arrangement on a pedestal table structure the depth of the room. Recreation notes: cane, marble and grey upholstery are the three materials, repeated without variation, and planting inside should be oversized and sculptural. Image extracted at native resolution from the official Capella press release PDF.", "src": "images/Capella Bangkok/0016 - Capella Bangkok - Phra Nakhon - conservatory dining room with skylight and banquettes.jpg", "source": "https://capellahotels.com/assets/docs/bangkok/10-2020_Capella_Bangkoks_Phra_Nakhon_Restaurant_ENG.pdf", "dimensions": "1276x852", "size": 188429}, {"number": "0018", "file": "0018 - Capella Bangkok - Phra Nakhon - indoor marble table setting with green glassware.jpg", "resort": "Capella Bangkok", "space": "Phra Nakhon", "description": "This close view of an indoor Phra Nakhon table shows the material palette at full size: a beige marble top with a dark stained timber edge and frame, white paper placemats, black ceramic plates, folded white napkins, green glass tumblers and brass cutlery, lit by a small brass table lamp with a posy of white flowers. The chairs are dark framed with woven backs, glimpsed at the edges. For a home version, the formula is a stone top, black plate, green glass and brass metalwork, with joinery kept dark enough to anchor the pale surfaces around it.", "src": "images/Capella Bangkok/0018 - Capella Bangkok - Phra Nakhon - indoor marble table setting with green glassware.jpg", "source": "https://suiteverdict.com/en/thailand/bangkok/capella-bangkok-verdict", "dimensions": "2560x1707", "size": 623979}, {"number": "0019", "file": "0019 - Capella Bangkok - Phra Nakhon - terrace at dusk with marble tables.jpg", "resort": "Capella Bangkok", "space": "Phra Nakhon", "description": "At dusk the Phra Nakhon terrace reads differently, with rows of white marble tables and black rattan chairs lit by small table lamps and the last light on the river, under a heavy tree canopy. The setting is the same furniture as the daytime terrace views but the mood depends on low warm light, dark silhouettes and the reflective water behind the rail. The source review describes vintage style table lamps, gold tinted glasses and brass cutlery in vintage Thai style at these tables. Keep outdoor lighting low, warm and at table height only. [below 1200px - best available]", "src": "images/Capella Bangkok/0019 - Capella Bangkok - Phra Nakhon - terrace at dusk with marble tables.jpg", "source": "https://happyhourasia.com/phra-nakhon-serves-authentic-cuisine-in-capella-bangkoks-relaxing-riverfront-setting/", "dimensions": "1170x780", "size": 490826}, {"number": "0020", "file": "0020 - Joali Maldives - Luxury Water Villa with Pool - bedroom with canopy net and turquoise pendant.jpg", "resort": "Joali Maldives", "space": "Luxury Water Villa with Pool", "description": "A king bed dressed in white linen with a taupe throw sits under a sheer canopy net, facing a wall of dark stained timber panels hand carved with palm frond reliefs. A turquoise glass disc pendant and matching wall disc act as the single colour accent, echoed in the ocean beyond the sliding doors. Note the blush toned flatweave rug with a faded botanical pattern, the woven drum pouf at the bed foot, open shelving with ceramics and books, a television panel painted with a wave motif, wall sconces in aged bronze, and full height sheer curtains softening the vaulted thatch lined ceiling.", "src": "images/Joali Maldives/0020 - Joali Maldives - Luxury Water Villa with Pool - bedroom with canopy net and turquoise pendant.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/luxury-water-villa-with-pool/", "dimensions": "2000x1126", "size": 309301}, {"number": "0021", "file": "0021 - Joali Maldives - Luxury Water Villa with Pool - living room with blush woven armchairs and library bar.jpg", "resort": "Joali Maldives", "space": "Luxury Water Villa with Pool", "description": "The separate living room pairs two blush pink woven swivel armchairs with a low grey sofa dressed in pink and dove cushions, arranged around a glossy dark wood drum coffee table on a monochrome patterned rug. Behind, a dark timber bar and library unit with brass framing holds glassware, books and small sculptures, flanked by carved palm relief panels and a large turquoise glass disc artwork. Recreating the look needs cane and rattan textures kept tonal, one saturated teal art piece per room, potted palms in woven baskets, and a wall of hat hooks and curated objects by the entry.", "src": "images/Joali Maldives/0021 - Joali Maldives - Luxury Water Villa with Pool - living room with blush woven armchairs and library bar.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/luxury-water-villa-with-pool/", "dimensions": "2000x1126", "size": 324286}, {"number": "0027", "file": "0027 - Joali Maldives - Four Bedroom Beach Residence with Pool - bedroom opening to garden terrace.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "A ground floor bedroom opens fully to a shaded garden terrace through sliding glass doors with sheer and taupe curtains. The bed carries white linen and a blush throw, matched by a woven blush swivel chair with a slate cushion and two cane terrace armchairs outside around a small table. Two black lattice lantern pendants hang from the thatched terrace roof, and a dark minibar cabinet with brass shelving stands by the wall. The scheme layers cream walls, pale stone floors, woven cane and rattan in honey tones, and soft pink textiles against dense green planting.", "src": "images/Joali Maldives/0027 - Joali Maldives - Four Bedroom Beach Residence with Pool - bedroom opening to garden terrace.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 306820}, {"number": "0031", "file": "0031 - Joali Maldives - Four Bedroom Beach Residence with Pool - dressing room with vanity and green marble panels.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The dressing room combines open wardrobe shelving in pale oak with a dark stained vanity desk and woven stool, lit by a mirror framed with globe bulbs in theatrical style. A stained glass door panel of green palm leaves and a full height panel of swirling green marble effect glass carry the bathroom motif through the suite, and a cylindrical rattan stool holds a woven tote. Brass shelf edging and black accessories keep the pale palette grounded. The design lesson is continuity: one coloured glass language links bath, dressing and bedroom, while storage stays open, shallow and hotel style.", "src": "images/Joali Maldives/0031 - Joali Maldives - Four Bedroom Beach Residence with Pool - dressing room with vanity and green marble panels.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 299706}, {"number": "0032", "file": "0032 - Joali Maldives - Four Bedroom Beach Residence with Pool - living room with shelving wall and blue sofa.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "A double height living room is organised around a full wall of dark timber shelving divided into square compartments displaying ceramics, books and sculpture, with a wave painted television panel at its centre and carved palm relief panels behind. Seating mixes a long blue grey sofa with exposed dark wood frame, woven swivel chairs and a pair of charcoal dining chairs on a blue patterned rug over banded stone floors. Tall sliding doors open to the pool terrace. To recreate, build the shelving as the artwork, keep upholstery in dusty blue and blush, and let one large plant soften the grid.", "src": "images/Joali Maldives/0032 - Joali Maldives - Four Bedroom Beach Residence with Pool - living room with shelving wall and blue sofa.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 316898}, {"number": "0034", "file": "0034 - Joali Maldives - Four Bedroom Beach Residence with Pool - outdoor shower with emerald tile wall.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The garden shower court is walled in vertically stacked emerald green glazed ceramic tiles with strong colour variation, set between blush plaster pillars and a slatted bamboo privacy screen. A black rain shower on a dark pole, a carved wooden stump side table holding flowers and folded towels, and dense tropical planting in greens complete the space, over pale gravel and stone paving. This is the boldest colour moment in the residence: one saturated tile wall, everything else natural. Recreating it needs handmade look tiles with tonal movement, not flat green, and timber screens left untreated.", "src": "images/Joali Maldives/0034 - Joali Maldives - Four Bedroom Beach Residence with Pool - outdoor shower with emerald tile wall.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 422974}, {"number": "0035", "file": "0035 - Joali Maldives - Four Bedroom Beach Residence with Pool - library with open shelving and woven chairs.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The residence library lines one wall with open dark timber and brass shelving filled with books, coral, ceramics and framed pieces, above a long dark wood desk with bamboo style legs and a brass lamp. Two woven armchairs in blush and cream with pink cushions are grouped with a turned dark wood side table, and carved timber panels and a patterned stair rail close the view. Lighting is warm and low from sconces and desk lamps. For recreation, treat the library as a lived in cabinet of curiosities: mixed natural specimens and books, no matching sets, upholstery kept pale.", "src": "images/Joali Maldives/0035 - Joali Maldives - Four Bedroom Beach Residence with Pool - library with open shelving and woven chairs.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 323834}, {"number": "0041", "file": "0041 - One&Only Reethi Rah - Lobby - wide view of reception pavilion.jpg", "resort": "One&Only Reethi Rah", "space": "Lobby", "description": "The reception pavilion is a vast open sided hall under a steeply pitched thatched roof with exposed dark timber trusses. Massive carved wooden columns stand on black polished terrazzo floors inlaid with teak strips. Low lounge sofas in white canvas with crimson red cushions line both sides, paired with woven rattan tub chairs and low wooden coffee tables on pale rugs. Oversized black wire cage drum pendants with cream shades hang at intervals. Geometric timber lattice screens filter daylight and garden views. A single timber reception desk sits on axis beneath a carved gable panel and patterned feature wall. [below 1200px - best available]", "src": "images/One&Only Reethi Rah/0041 - One&Only Reethi Rah - Lobby - wide view of reception pavilion.jpg", "source": "https://theluxurytravelexpert.com/review-one-only-reethi-rah-maldives/", "dimensions": "1000x750", "size": 361590}, {"number": "0049", "file": "0049 - One&Only Reethi Rah - Botanica restaurant - orchid house dining room.jpg", "resort": "One&Only Reethi Rah", "space": "Botanica restaurant", "description": "Dinner inside the Botanica orchid house is served under a high pitched glasshouse roof of black steel trusses and translucent shade panels, with ceiling fans and small star like downlights. Dark stained timber dining tables are paired with formal carved chairs whose shaped splat backs and tan seats recall colonial plantation furniture. Both long walls are tiered planting benches dense with flowering orchids, each tier edged with tiny fairy lights, so guests dine between two banks of blooms. The floor is raked pale sand. Palette: black framework, dark wood, white and magenta orchid flowers, warm pinpoint lighting. [below 1200px - best available]", "src": "images/One&Only Reethi Rah/0049 - One&Only Reethi Rah - Botanica restaurant - orchid house dining room.jpg", "source": "https://www.purelymaldives.co.uk/resorts/view/one-only-reethi-rah", "dimensions": "850x638", "size": 335958}, {"number": "0050", "file": "0050 - One&Only Reethi Rah - Beach Villas - living room with lattice ceiling.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The villa living room runs under a soaring pitched ceiling of dark timber boards crossed by lashed bamboo poles in a diamond lattice. Freestanding screen walls alternate cream panels with dark woven coconut shell mosaic, separating living, sleeping and bathing zones without doors. A long oatmeal linen sofa and chaise carry cushions in cream, sage and a red medallion print, arranged around a round white coffee table and timber armchairs with woven backs. Polished terrazzo floors with dark inlay bands, a patterned rust toned rug, and full height sliding doors open to a canopied daybed, plunge pool and beach beyond.", "src": "images/One&Only Reethi Rah/0050 - One&Only Reethi Rah - Beach Villas - living room with lattice ceiling.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1324", "size": 583154}, {"number": "0051", "file": "0051 - One&Only Reethi Rah - Beach Villas - master bedroom with ocean view.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The master bedroom is arranged symmetrically on the ocean view, the king bed centred on a wide timber framed window with white linen, taupe cushions and a mustard yellow bolster. At its foot, two pale upholstered timber armchairs with red medallion print cushions flank a round drum pedestal table in warm wood with a dark woven top. Round timber bedside cabinets carry square white pendant lamps. To one side, a black framed minibar cabinet combines mirror, glass shelves and drawers faced in coconut shell and woven fibre; opposite stands a matching luggage cabinet on X frame legs. Woven mosaic wall panels and lashed bamboo ceiling beams complete the scheme.", "src": "images/One&Only Reethi Rah/0051 - One&Only Reethi Rah - Beach Villas - master bedroom with ocean view.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1150", "size": 758992}, {"number": "0055", "file": "0055 - One&Only Reethi Rah - Beach Villas - veranda lounge with teal daybed.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The covered veranda lounge is furnished as an outdoor living room: a very long low bench daybed in dark timber with a taupe mattress and a continuous teal bolster back, dressed with teal cushions and leaf patterned pillows in aqua and white. Two barrel back chairs woven in grey cord sit at a round white dining table with a wooden bowl of fruit. Above, the open gable shows thatch laid over bamboo laths and lashed bamboo trusses, framing a wall of tropical planting that acts as the room backdrop. Terrazzo flooring with dark inlay continues outside, blurring the indoor outdoor boundary.", "src": "images/One&Only Reethi Rah/0055 - One&Only Reethi Rah - Beach Villas - veranda lounge with teal daybed.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1551", "size": 706415}, {"number": "0056", "file": "0056 - One&Only Reethi Rah - Beach Villas - dining room with coconut shell table.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The villa dining area centres on a rectangular table whose top is a mosaic of coconut shell pieces in variegated browns, carried on splayed timber legs. Six sculpted dining chairs in warm mid tone wood have curved crest rails, padded grey seats and slender tapered legs. Behind, a pale grey sofa faces the beach through wide sliding doors beneath a thatched veranda. Black metal framed consoles with timber tops hold books, a star sculpture and flowers, and two framed black and white photographs hang above. Polished terrazzo with dark border inlay, woven screen panels and bamboo lashed ceiling beams maintain the villa material palette.", "src": "images/One&Only Reethi Rah/0056 - One&Only Reethi Rah - Beach Villas - dining room with coconut shell table.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1510", "size": 659432}, {"number": "0059", "file": "0059 - The Nautilus Maldives - Beach Residence with Private Pool - curved living room with orange ikat cushions.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "Ground floor living room planned on a curve, with a long low sofa in natural linen following the wall, piled with solid orange cushions and orange and gold ikat cushions. Two round coral orange coffee tables with dark turned legs and patterned tops sit on an orange and ochre abstract rug over pale parquet. Beyond are a slatted timber television console, a table lamp with a stacked openwork rattan base, a woven chandelier over the dining table, and sage woven dining chairs. A cream macrame hanging against a round orange wall disc anchors the bohemian layering, and full height glazing opens to the deck, pool and ocean.", "src": "images/The Nautilus Maldives/0059 - The Nautilus Maldives - Beach Residence with Private Pool - curved living room with orange ikat cushions.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x900", "size": 183062}, {"number": "0060", "file": "0060 - The Nautilus Maldives - Beach Residence with Private Pool - wet bar and dining detail with woven stools.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "Close view of the ground floor wet bar and dining corner. Two high stools pair sage green woven wrap around backs with pale timber legs and foot rails, set at a counter fronted in fine vertical strips with a floating shelf holding dark glass vessels above. Matching woven dining chairs with grey seat pads surround a round pale wood table set with turquoise glassware. Oversized ribbed rattan urns, a chevron grooved timber door and a table lamp with three stacked rattan spheres on a round side table complete the scheme, over basketweave parquet in warm oak tones.", "src": "images/The Nautilus Maldives/0060 - The Nautilus Maldives - Beach Residence with Private Pool - wet bar and dining detail with woven stools.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x900", "size": 179464}, {"number": "0062", "file": "0062 - The Nautilus Maldives - Beach Residence with Private Pool - upstairs king bedroom opening to ocean balcony.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "Upstairs king bedroom in white linen, dressed with a central bolster, patterned cushions piped in orange and a painterly bed runner in orange, ochre and taupe stripes. A buttoned grey bench at the foot holds two white and gold lattice cushions, and a round orange and yellow rug softens pale geometric tiled flooring. Timber framed folding doors open to a balcony with wicker armchairs and a round pedestal table under the thatch, facing the ocean. Through the rear doorway, the bathroom shows a round patterned pouffe, a glass shower enclosure and a white robe, linking the sleep and bath zones.", "src": "images/The Nautilus Maldives/0062 - The Nautilus Maldives - Beach Residence with Private Pool - upstairs king bedroom opening to ocean balcony.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x900", "size": 197986}, {"number": "0069", "file": "0069 - The Nautilus Maldives - Nautilus Retreat with Private Pool - living room under domed thatch ceiling with macrame chandelier.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Reverse view of the circular living room, taken for its ceiling: a high domed roof of woven panels and exposed rafters, hung with a large hand knotted macrame chandelier with a beaded drop. Below, a high backed mustard wing chair and the curved cream sofa with yellow floral cushions sit around the round yellow coffee table, beside a drum side table carrying the stacked sphere rattan lamp. A cream macrame hanging is mounted on a round yellow wall disc, echoing the motif used in the beach residence, and a chevron grooved timber door closes the wall. Glazed doors run the length of the deck side.", "src": "images/The Nautilus Maldives/0069 - The Nautilus Maldives - Nautilus Retreat with Private Pool - living room under domed thatch ceiling with macrame chandelier.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x980", "size": 211128}, {"number": "0070", "file": "0070 - The Nautilus Maldives - Nautilus Retreat with Private Pool - curved bedroom in yellow scheme with deck doors.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Curved bedroom in the yellow colourway, the king bed in white linen with a yellow and taupe painterly runner, lattice patterned cushions and a cylindrical bolster, backed by a pale timber headboard shelf with arched reading lamps. A buttoned cream bench stands at the foot, and a long low slatted timber console holds a turquoise glass bowl. Three tall glazed openings frame the deck and ocean, the middle one open. Through folding doors, the living room shows a rounded mustard chair, yellow tables and a sunburst mirror. Pale parquet in a chevron layout and a yellow abstract rug unify both rooms.", "src": "images/The Nautilus Maldives/0070 - The Nautilus Maldives - Nautilus Retreat with Private Pool - curved bedroom in yellow scheme with deck doors.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x900", "size": 233722}, {"number": "0076", "file": "0076 - Raffles Bali - Residence - master bedroom with bed bench and balcony.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Master bedroom with a coffered, high pitched ceiling in rich teak toned timber and walls panelled in fluted wood and soft taupe fabric. The king bed is dressed in crisp white linen with navy and terracotta cushions, and a dark wood bed bench with navy bolster cushions sits at its foot, a signature Raffles touch. Beside the bed, marble effect stone panels back floating nightstands with box frame lamps. A lounge chair and ottoman sit by full height sliding doors opening to a balcony with garden views. Polished hardwood floors are softened by a plain cream rug.", "src": "images/Raffles Bali/0076 - Raffles Bali - Residence - master bedroom with bed bench and balcony.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 630516}, {"number": "0077", "file": "0077 - Raffles Bali - Residence - bedroom suite with sitting area and carved screen.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Second bedroom suite arranged as a private apartment, with its own sitting area in the foreground. A cream sofa with navy and woven tan cushions faces a low stone topped coffee table on a blue patterned rug, while the bed sits beyond a carved timber screen panel with a traditional Balinese motif, which zones sleep from sitting without a wall. Fitted wardrobes in warm wood line the far wall, and glazed doors on both sides bring in garden light. The lesson is zoning with screens, rugs and ceiling coffers in one continuous timber and cream scheme.", "src": "images/Raffles Bali/0077 - Raffles Bali - Residence - bedroom suite with sitting area and carved screen.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 587788}, {"number": "0078", "file": "0078 - Raffles Bali - Residence - dining room with long dark table and rattan chairs.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Formal dining room for twelve under a soaring pitched ceiling of warm timber boards. One very long, dark stained plank table runs the length of the room, set with white napkins, glassware and a low floral centrepiece. The chairs are the focal craft piece, high backed woven rattan with curved crest rails and plump patterned seat cushions, light in colour against the dark table. Walls of glass on three sides frame jungle and ocean, a carved dark wood screen closes one end, and a single long pendant hangs over the table. Hardwood floors run throughout.", "src": "images/Raffles Bali/0078 - Raffles Bali - Residence - dining room with long dark table and rattan chairs.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 703277}, {"number": "0079", "file": "0079 - Raffles Bali - Residence - open plan living room and stone kitchen island.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Open plan living and show kitchen in one double height space, designed for entertaining. A long island in warm wood cabinetry with a thick grey veined stone top anchors the room, lit by a cluster of slim black pendant rods at different heights. Beyond it, low cream sofas and armchairs with dark frames group around coffee tables on a pale rug, with a television console against the glass wall. Ceiling fans, cove lit timber ceilings and full height glazing keep the large volume intimate. The scheme mixes stone, teak toned joinery and black metal accents.", "src": "images/Raffles Bali/0079 - Raffles Bali - Residence - open plan living room and stone kitchen island.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 721087}, {"number": "0080", "file": "0080 - Raffles Bali - Residence - study with marble desk and display shelving.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Private study and entertainment room with a dramatic black marble desk slab in the foreground, paired with sculptural grey upholstered desk chairs. Behind, a full wall of open display shelving in warm timber is backlit and styled with Balinese artefacts, a carved gold toned plaque, masks, ceramics, books and framed photographs, with a wall mounted television at its centre. A black multi disc chandelier adds a modern note against a dark woven ceiling panel. Glazed doors open to the pool terrace. The takeaway is museum style shelving, objects in ones and twos, and generous spacing.", "src": "images/Raffles Bali/0080 - Raffles Bali - Residence - study with marble desk and display shelving.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 654096}, {"number": "0083", "file": "0083 - Mandapa - Riverfront Pool Villa - living room with hand painted panels.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "Open sided living room in dark stained timber centred on a woven rattan sofa dressed with ivory cushions and patterned throw pillows in grey, gold and cream. A round black pedestal coffee table carries a tea set and a small floral arrangement, balanced by a cylindrical dark wood cabinet at the side. Behind the sofa, tall hand painted wall panels in muted gold and sage show delicate botanical motifs, the signature art treatment of the villas. Full height glass doors open to a planted terrace, and a pale woven rug softens the polished timber floor.", "src": "images/Mandapa/0083 - Mandapa - Riverfront Pool Villa - living room with hand painted panels.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 771740}, {"number": "0085", "file": "0085 - Mandapa - Riverfront Pool Villa - bedroom with murals and terrace doors.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "Wide bedroom view showing how the villa layers art, textile and timber. Large hand painted murals of Balinese landscape and flora cover the wall panels around a window seat dressed in cream with ochre cushions. A green upholstered lounge chair and small black side table sit beside folding glass doors that open to a furnished terrace. The bed, partly seen, carries a vivid floral patterned throw in coral and blue over white linen. A woven ceiling pendant, natural fibre rug and dark wood framing complete a rich but restful scheme.", "src": "images/Mandapa/0085 - Mandapa - Riverfront Pool Villa - bedroom with murals and terrace doors.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 928792}, {"number": "0086", "file": "0086 - Mandapa - Riverfront Pool Villa - king bedroom with mural panel and daybed.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "King bedroom arranged symmetrically in dark stained wood, the bed dressed in crisp white linen with a low black bench at its foot holding folded books. Behind the bed, a tall window frames tropical planting, flanked by a large colourful mural panel with peacock and floral detailing. To the left, a built in daybed with cream cushions and a coral throw sits under a second garden window, with a small round black table in front. Stone sculpture on a floating shelf, hanging lantern pendants and a pale woven rug finish the composition.", "src": "images/Mandapa/0086 - Mandapa - Riverfront Pool Villa - king bedroom with mural panel and daybed.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 953519}, {"number": "0091", "file": "0091 - Mandapa - Mandapa Spa - relaxation lounge with river view.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Spa relaxation lounge arranged along a glass wall above the Ayung River. A curved low sofa in pale upholstery carries cushions in leaf green and terracotta, facing the water through full height sliding glass. Beside it stands a sculptural round side table in dark turned wood, set with a tea service and a bowl of fruit. Polished timber floors reflect the daylight, and carved wooden screens partly divide the seating bays. The recipe to copy is simple: one strong sculptural table, plain upholstery, two saturated cushion colours and an uninterrupted view.", "src": "images/Mandapa/0091 - Mandapa - Mandapa Spa - relaxation lounge with river view.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 872199}, {"number": "0093", "file": "0093 - Mandapa - Mandapa Spa - reception and retail gallery.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Long reception and retail gallery in the spa, lined on one side with dark timber display shelving holding ceramics, oils and treatment products under warm picture lighting. A central stone topped consultation table with a carved geometric base is paired with leather and wood chairs, while a low credenza in matching dark wood carries table lamps and a tall arrangement of red tropical flowers. Coffered ceilings, travertine style stone floors and brass pendants give the space a calm, residential formality quite different from a typical hotel spa desk.", "src": "images/Mandapa/0093 - Mandapa - Mandapa Spa - reception and retail gallery.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "1920x1302", "size": 368899}, {"number": "0100", "file": "0100 - Mandapa - Library - open pavilion lounge with woven pendants.jpg", "resort": "Mandapa", "space": "Library", "description": "The Library is an open sided timber pavilion lounge beside the main pool, furnished for afternoon tea and quiet reading. Round dark wood tables are paired with armchairs that combine curved timber frames with woven cane style backs and patterned upholstery. Large woven rattan pendants hang from the high pitched, raftered ceiling, and patterned stone tiles in grey and terracotta run across the floor. Dark wood bookcases and cabinets line the inner wall, while the open sides frame the pool, rice fields and forest. Official resort photograph, the only Library image the resort itself publishes.", "src": "images/Mandapa/0100 - Mandapa - Library - open pavilion lounge with woven pendants.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/dining/", "dimensions": "1920x1280", "size": 472846}, {"number": "0101", "file": "0101 - Mandapa - Library - afternoon tea setting with framed deity painting.jpg", "resort": "Mandapa", "space": "Library", "description": "Second verified view of The Library, captioned as The Library in the gallery of a UK luxury travel specialist. A large gilt framed Balinese painting of a multi armed deity dominates the dark timber wall above a painted storage chest with gold detailing and a row of small candles. In front, steam bent style wooden armchairs with navy cushions surround a round table laid for the signature afternoon tea, with a tiered stand and teapot. A woven globe pendant hangs overhead, and folding doors open to the veranda, pool and gardens beyond. [below 1200px - best available]", "src": "images/Mandapa/0101 - Mandapa - Library - afternoon tea setting with framed deity painting.jpg", "source": "https://prestburytravel.co.uk/hotels/8374/mandapa-a-ritz-carlton-reserve", "dimensions": "900x600", "size": 251255}, {"number": "0103", "file": "0103 - Amanoi - Amanoi Ocean Pool Villa - living room opening to sea view terrace.jpg", "resort": "Amanoi", "space": "Amanoi Ocean Pool Villa", "description": "Daytime living room photographed from inside looking straight out to the sea, so the furniture reads as a layered foreground to the view. A grey upholstered sofa with rounded cushions sits left, paired with low slung timber armchairs with dark seat pads around a round pedestal coffee table holding a fruit bowl. Narrow side tables carry books and a small lantern. Red cylindrical lanterns hang either side of full height folding doors that open completely onto a terrace with two further armchairs and a table, demonstrating the seamless indoor outdoor plan, pale neutral textiles and dark timber contrast used throughout the villa.", "src": "images/Amanoi/0103 - Amanoi - Amanoi Ocean Pool Villa - living room opening to sea view terrace.jpg", "source": "https://www.aman.com/resorts/amanoi/accommodation/pavilions-villas/amanoi-ocean-pool-villa", "dimensions": "2560x1580", "size": 632650}, {"number": "0110", "file": "0110 - Amanoi - The Restaurant - dining room with white linen and black lamps.jpg", "resort": "Amanoi", "space": "The Restaurant", "description": "Wide interior of the main dining room, set for service with rectangular tables dressed in crisp white linen, glassware and folded napkins, surrounded by wooden framed chairs with dark woven backs and cream seats. A cream banquette runs along one side. Behind the tables, tall illuminated timber display cabinets hold large black lacquered urns and vessels, matched by oversized black table lamps with drum shades on side consoles. Dark ceilings, warm backlighting and restrained black, cream and honey timber tones give the formal room its evening mood, a useful template for quiet, layered restaurant lighting and display shelving.", "src": "images/Amanoi/0110 - Amanoi - The Restaurant - dining room with white linen and black lamps.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "2000x1235", "size": 478574}, {"number": "0112", "file": "0112 - Amanoi - The Restaurant - pavilion interior with lattice screens and columns.jpg", "resort": "Amanoi", "space": "The Restaurant", "description": "Long view through the Central Pavilion interior toward full height latticed timber screens, showing the restaurant lounge area furnished with grouped wooden armchairs, cushioned seats and low tables on a highly polished dark floor that mirrors the columns. Massive round grey columns carry the high pitched timber ceiling, and carved dark figures and a large floral arrangement on plinths provide the only ornament. Warm light glows through the lattice at the far end. The scale lesson is clear: very tall, simple architecture, furniture kept low and sparse, and screens used instead of solid walls to divide the space.", "src": "images/Amanoi/0112 - Amanoi - The Restaurant - pavilion interior with lattice screens and columns.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "2560x1580", "size": 537736}, {"number": "0116", "file": "0116 - Amanoi - The Bar - long timber bar counter with columns.jpg", "resort": "Amanoi", "space": "The Bar", "description": "Wide evening view along the Bar, centred on a very long, low timber bar counter with a dark top, fronted by a row of tan leather bar chairs. Massive pale columns divide the counter from a lounge area of low sofas and small round tables to the left, all under a high pitched timber ceiling with exposed structure. Warm light glows from latticed timber screens and glass cabinets behind the counter, where a bartender works. The design takeaway is length and repetition: one continuous counter, identical seating, and amber backlighting creating atmosphere without decoration or clutter.", "src": "images/Amanoi/0116 - Amanoi - The Bar - long timber bar counter with columns.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "2560x1580", "size": 536606}, {"number": "0128", "file": "0128 - Four Seasons Resort Koh Samui - Specialty Villas - Island Residence living and dining room.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "The living and dining room of the one bedroom Island Residence combines polished hardwood floors with a high open ceiling and full height glass doors. Two woven armchairs with cream and patterned cushions face a pale upholstered sofa across paired drum side tables in natural wood, stacked with books and ceramics. Behind, a timber dining table with six woven chairs and turquoise cushions stands ready for indoor meals, lit by daylight from three sides. Tall potted palms, carved details and a muted palette of cream, sand and sea green complete a calm, collected interior. [below 1200px - best available]", "src": "images/Four Seasons Resort Koh Samui/0128 - Four Seasons Resort Koh Samui - Specialty Villas - Island Residence living and dining room.jpg", "source": "https://hurlinghamtravel.co.uk/hotel/four-seasons-resort-koh-samui", "dimensions": "1100x671", "size": 263986}, {"number": "0132", "file": "0132 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Main dining hall with woven chairs.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "KOH Thai Kitchen", "description": "The main dining hall at KOH Thai Kitchen is a grand open pavilion with a steeply pitched timber ceiling, exposed trusses and slowly turning ceiling fans. Rows of square wooden tables are set with glassware and folded napkins, surrounded by woven rattan armchairs with patterned seat cushions in cream and soft blue. Dark hardwood floors reflect the warm late light, and the open sides frame jungle and sea views between massive round columns. Botanical artworks and low planting complete a room that feels both ceremonial and relaxed, unmistakably southern Thai in spirit.", "src": "images/Four Seasons Resort Koh Samui/0132 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Main dining hall with woven chairs.jpg", "source": "https://www.fourseasons.com/kohsamui/dining/restaurants/koh/", "dimensions": "2560x1642", "size": 1125546}, {"number": "0136", "file": "0136 - Four Seasons Resort Koh Samui - KOH Bar - Lounge pavilion with rattan armchairs and oversized sofas.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "KOH Bar", "description": "The KOH Bar lounge fills a high timber pavilion with blocky woven rattan armchairs, oversized daybed sofas and low square coffee tables. Cushions mix burnt orange solids with cream and rust geometric patterns, warming the dark hardwood floor and the massive round columns. Rope wrapped beam joints, a woven ceiling, pierced friezes and clusters of woven pendant lights add crafted Thai detail overhead, while folding glass doors open one whole side to the terrace and trees. Staff serve wine and cocktails at the tables, underlining that this is a drinking lounge, not a dining room.", "src": "images/Four Seasons Resort Koh Samui/0136 - Four Seasons Resort Koh Samui - KOH Bar - Lounge pavilion with rattan armchairs and oversized sofas.jpg", "source": "https://www.fourseasons.com/kohsamui/dining/", "dimensions": "2560x1707", "size": 1055413}, {"number": "0138", "file": "0138 - Amanpuri - Pavilion - bedroom with lattice timber headboard wall.jpg", "resort": "Amanpuri", "space": "Pavilion", "description": "A symmetrical pavilion bedroom built around a full height lattice headboard wall of dark stained timber framing lighter wood panels in a strict grid. The low platform king bed in white striped cotton sits on chunky round timber legs, flanked by oval dark wood side tables, black swing arm reading lamps and tall carved wooden paddle sculptures mounted on the cream walls. Polished teak floorboards, a black vase of white orchids and lotus bud dishes complete the restrained palette. To recreate it, pair geometric timber screening with sculptural tribal art, low rounded furniture and warm uplighting.", "src": "images/Amanpuri/0138 - Amanpuri - Pavilion - bedroom with lattice timber headboard wall.jpg", "source": "https://www.aman.com/resorts/amanpuri/gallery", "dimensions": "2560x1582", "size": 306989}, {"number": "0143", "file": "0143 - Amanpuri - Eight-Bedroom Ocean Villa - lounge with leather armchairs and ocean view.jpg", "resort": "Amanpuri", "space": "Eight-Bedroom Ocean Villa", "description": "A grand open lounge under a high timber roof, where rows of polished round columns and diagonal braces frame glass walls looking to the sea. Seating is low and generous: taupe leather armchairs, leather daybeds with bolster arms and a long sofa grouped around oversized dark wood coffee tables on a muted rug. A tripod telescope, a bronze figure sculpture on a stone plinth and a carved wooden orb act as focal objects, with a rubble stone wall behind. To recreate it, use leather in warm greys, very large low tables, ceiling fans and museum scale art against the view.", "src": "images/Amanpuri/0143 - Amanpuri - Eight-Bedroom Ocean Villa - lounge with leather armchairs and ocean view.jpg", "source": "https://www.aman.com/resorts/amanpuri/accommodation/villas", "dimensions": "1600x988", "size": 1543163}, {"number": "0145", "file": "0145 - Amanpuri - Villas - living room with celadon daybeds and pedestal table.jpg", "resort": "Amanpuri", "space": "Villas", "description": "A formal villa living room arranged with strict symmetry around a round burl wood pedestal table with a stepped, stacked base. Pale celadon daybed platforms with Thai triangular cushions face each other across dark stone tiles, fronted by a low lacquered tea tray. Behind, glazed timber doors and lattice screens reveal display cabinets of ceramics and a media room, flanked by Buddha head sculptures on plinths and silvered bamboo armchairs. The timber boarded ceiling and restrained green, brown and cream palette show how to use symmetry, collectable objects and one statement table to anchor a large room.", "src": "images/Amanpuri/0145 - Amanpuri - Villas - living room with celadon daybeds and pedestal table.jpg", "source": "https://www.aman.com/resorts/amanpuri/accommodation/villas", "dimensions": "2560x2560", "size": 1114382}, {"number": "0186", "file": "0186 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - carved screen headboard wall detail with bedside pendant.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "A detail study of the suite headboard wall, where framed teak panels carved with scrolling foliage run floor to ceiling behind the bed, their openwork backed so the pattern reads as shadow and texture. A single fabric shaded cylindrical pendant drops beside the pillow, and the low nightstand is woven cane fronted timber. In a wall niche sits a small stone guardian statue, spotlit like gallery art, while a pale lounge chair with a patterned cushion waits in the corner. The lesson for recreation is layering: carved wood, woven cane, stone sculpture and plain linen in one restrained palette.", "src": "images/Four Seasons Resort Bali at Sayan/0186 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - carved screen headboard wall detail with bedside pendant.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 885109}, {"number": "0187", "file": "0187 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - mezzanine living room with woven armchairs and valley windows.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "The upper living level of the duplex suite pairs a pale grey sofa with low woven rattan armchairs and a green upholstered bench, arranged around the stair rail so the seating group floats above the floor below. A tall floor lamp with a stacked, textured column base and drum shade anchors one corner, and louvered teak shutters frame floor to ceiling windows over the river valley. Beyond glazed doors a dining nook repeats the palette. Recreating it requires furniture kept low and leggy, natural fibre upholstery, dark timber trim throughout, and pattern confined to a few cushions and the woven chair backs.", "src": "images/Four Seasons Resort Bali at Sayan/0187 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - mezzanine living room with woven armchairs and valley windows.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 963596}, {"number": "0188", "file": "0188 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - window reading corner with louvered shutters and rattan chair.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "A corner reading nook wrapped in teak louvered shutters and tall windows, furnished with a pale sofa dressed in oversized green floral cushions and a round swivel chair in bent rattan with floral upholstery. A small dark timber side table carries a sculptural lamp and a vase of white flowers, and the polished timber floor is left bare to show its grain. The design move to copy is the shuttered window wall itself: adjustable louvres replace curtains, controlling light and privacy while adding strong vertical rhythm, and one bold floral textile repeated on chair and cushions ties the whole corner together.", "src": "images/Four Seasons Resort Bali at Sayan/0188 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - window reading corner with louvered shutters and rattan chair.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 1056774}, {"number": "0192", "file": "0192 - Four Seasons Resort Bali at Sayan - One-Bedroom Villa - bedroom opening to terrace dining with statue niche.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "One-Bedroom Villa", "description": "A second angle on the villa bedroom showing its full indoor outdoor plan: bed with plum cushions and a woven bench, a stone deity statue set into a lit wall niche, framed Balinese artwork, and a low carved cabinet beneath it. Teak folding louvered doors open to a covered terrace set with a dining table and timber chairs above the valley, while a separate desk sits by shuttered windows. The palette is cream plaster, warm teak and deep plum accents. To copy it, treat the niche statue and artwork as the room art programme and let one accent colour carry cushions and upholstery.", "src": "images/Four Seasons Resort Bali at Sayan/0192 - Four Seasons Resort Bali at Sayan - One-Bedroom Villa - bedroom opening to terrace dining with statue niche.jpg", "source": "https://www.fourseasons.com/sayan/photos-and-videos/", "dimensions": "2560x1568", "size": 893384}, {"number": "0197", "file": "0197 - Four Seasons Resort Bali at Sayan - Sacred River Spa - relaxation lounge with patterned chairs and bamboo screens.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Sacred River Spa", "description": "Inside the spa relaxation lounge, barrel back lounge chairs upholstered in blue grey patterned fabric face each other across small sculptural black side tables, under a pitched ceiling of bamboo and dark rafters. One wall is screened with vertical bamboo poles of varied tone, another is a long honed timber counter with orchids and ceramics, and the floor is large format grey stone tile. A therapist kneels in a tea service ritual at the centre. Recreation notes: pattern belongs on the chair fabric alone, structure stays dark timber and bamboo, and fresh orchids plus handmade ceramics provide the only decoration needed.", "src": "images/Four Seasons Resort Bali at Sayan/0197 - Four Seasons Resort Bali at Sayan - Sacred River Spa - relaxation lounge with patterned chairs and bamboo screens.jpg", "source": "https://press.fourseasons.com/content/fourseasons_pressroom/printView.html?pageToPrint=%2Fcontent%2Ffourseasons_pressroom%2Fen%2Fnews%2Fsayan%2F2024%2Fsacred_river_spa_rel", "dimensions": "2560x1707", "size": 1217560}, {"number": "0215", "file": "0215 - The Datai Langkawi - Canopy Suite - living and dining room with slatted timber cornice.jpg", "resort": "The Datai Langkawi", "space": "Canopy Suite", "description": "Open plan living and dining room in the main building, defined by a continuous slatted timber cornice at ceiling level. Curved barrel armchairs in cream fabric with dark timber side panels face grey sofas dressed with mustard yellow, charcoal and black and white patterned cushions. Two low black oval coffee tables carry glass hurricane candles, and a tall dark timber minibar cabinet with folding doors and warm internal lighting stands on legs against the wall. Beyond, an oval timber dining table with cream upholstered chairs sits under a large pleated white pendant, with torch style floor lamps, mirrored panelling and polished timber floors.", "src": "images/The Datai Langkawi/0215 - The Datai Langkawi - Canopy Suite - living and dining room with slatted timber cornice.jpg", "source": "https://www.thedatai.com/accommodation/the-canopy-collection/canopy-suite/", "dimensions": "2448x1633", "size": 496682}, {"number": "0217", "file": "0217 - The Datai Langkawi - The Datai Suite - dining room with woven chairs and sunburst wall disc.jpg", "resort": "The Datai Langkawi", "space": "The Datai Suite", "description": "Dining and living space divided by round dark timber columns under a coffered timber ceiling panel with cove lighting. Six dining chairs with tightly woven basketweave backs, cream seat pads and loose white cushions surround a round polished timber table with a raised fruit compote. On the white wall hangs a large circular sunburst disc in dark patinated metal, spotlit from above. A timber desk with an orchid and a black ceramic urn separates the dining area from a grey sofa lounge with a low timber coffee table. Torch style floor lamps, textured grey rugs and dark timber floors hold the calm, earthy palette together.", "src": "images/The Datai Langkawi/0217 - The Datai Langkawi - The Datai Suite - dining room with woven chairs and sunburst wall disc.jpg", "source": "https://www.thedatai.com/accommodation/the-canopy-collection/the-datai-suite/", "dimensions": "2448x1633", "size": 511984}, {"number": "0221", "file": "0221 - The Datai Langkawi - One-Bedroom Beach Villa - living pavilion opening to courtyard pool.jpg", "resort": "The Datai Langkawi", "space": "One-Bedroom Beach Villa", "description": "Open sided living pavilion with a high pitched raftered timber ceiling and full height glass doors. In the foreground, a massive single slab timber coffee table on black block legs holds black and gold ceramic vessels and a book, over a grey rug with a raised organic pattern. Cane backed armchairs with deep cream cushions group around it, and a timber dining table with matching woven cane chairs stands by the glass wall. Beyond the sliding doors, sun loungers and an umbrella sit beside the private pool against a wall of rough grey rubble stone, the resort signature boundary treatment.", "src": "images/The Datai Langkawi/0221 - The Datai Langkawi - One-Bedroom Beach Villa - living pavilion opening to courtyard pool.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1708", "size": 1361931}, {"number": "0228", "file": "0228 - The Datai Langkawi - The Dining Room - poolside terrace with curved armchairs.jpg", "resort": "The Datai Langkawi", "space": "The Dining Room", "description": "Terrace seating of the main restaurant under a slatted timber canopy carried on slender angled columns, overlooking the main pool. Square white topped tables on fluted dark timber pedestal bases are set for breakfast with white ceramics and small stone vases of flowers. The chairs are the design focus: curved timber armchairs with wraparound arms and cream upholstered backs and seats, repeated in rows across the pale stone tiles. Cylindrical cream pendants hang from the canopy. Beyond the pool, sun loungers with white umbrellas and a shingled pavilion roof sit against dense rainforest, in a palette of cream, pale stone and warm timber.", "src": "images/The Datai Langkawi/0228 - The Datai Langkawi - The Dining Room - poolside terrace with curved armchairs.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1708", "size": 1025101}, {"number": "0229", "file": "0229 - The Datai Langkawi - The Lobby Lounge - lounge pavilion with sunken seating and bar.jpg", "resort": "The Datai Langkawi", "space": "The Lobby Lounge", "description": "Grand open lounge pavilion under a soaring pitched timber roof with exposed rafters, ceiling fans and warm uplighting along the beams. In the foreground, a sunken seating pit of long cream banquettes is dressed with black and white geometric patterned cushions and deep green and ochre accents, grouped around round hammered metal drum tables with candle votives and low cream swivel lounge chairs. To the left, a long black stone bar with patterned seat stools runs towards a raised deck with a grand piano, armchairs and torch style lamps, all facing the open side and its view over the rainforest canopy to the sea.", "src": "images/The Datai Langkawi/0229 - The Datai Langkawi - The Lobby Lounge - lounge pavilion with sunken seating and bar.jpg", "source": "https://www.thedatai.com/dining/the-lobby-lounge/", "dimensions": "2560x1709", "size": 1035139}, {"number": "0366", "file": "0366 - The Brando - Three Bedroom Villa - living and dining room under pandanus vault.jpg", "resort": "The Brando", "space": "Three Bedroom Villa", "description": "The great room of the three bedroom villa, a double height space under a dramatic woven pandanus vault with exposed timber trusses and ceiling fans. A long marble topped dining table seats eight in textured oatmeal upholstered chairs. A low open timber credenza with ceramic vessels divides dining from the media wall, which is timber panelled with an inset screen. Full height sliding glass and cream curtains open to the pool deck and beach. Recreate with a woven vaulted ceiling as the hero, one long shared dining table, and low horizontal furniture that never competes with the roof.", "src": "images/The Brando/0366 - The Brando - Three Bedroom Villa - living and dining room under pandanus vault.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2500x1879", "size": 997170}, {"number": "0389", "file": "0389 - Constance Prince Maurice - Junior Suite Beachfront - bedroom with draped poster bed and X frame bench.jpg", "resort": "Constance Prince Maurice", "space": "Junior Suite Beachfront", "description": "Portrait view of the suite bedroom built around a tall carved dark wood poster bed dressed in white linen, a pleated fabric canopy panel and spice toned cushions, with an X frame upholstered bench at its foot. The pitched ceiling is lined in woven rattan under the thatch, floors are warm varnished timber, and a writing desk with an oval mirror and shell toned ceramics sits to one side. To recreate the look, pair a raised four poster bed with cream silk drapes, a cross leg bench, rattan ceiling cladding and bedside lamps with drum shades.", "src": "images/Constance Prince Maurice/0389 - Constance Prince Maurice - Junior Suite Beachfront - bedroom with draped poster bed and X frame bench.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "1771x2560", "size": 751844}, {"number": "0394", "file": "0394 - Constance Prince Maurice - Villa on Stilts - bedroom with teal cushions and louvred deck doors.jpg", "resort": "Constance Prince Maurice", "space": "Villa on Stilts", "description": "Villa bedroom with a high vaulted ceiling lit by a warm cove, a carved dark wood bed dressed with a brocade style throw and teal cushions over the spice route palette. Louvred timber doors open to the deck, with an armchair, pedestal table and upholstered bench completing the room on polished wood floors. Recreate with teal and sand silk cushions, a patterned throw, shutter doors and a ceiling fan.", "src": "images/Constance Prince Maurice/0394 - Constance Prince Maurice - Villa on Stilts - bedroom with teal cushions and louvred deck doors.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1709", "size": 716631}, {"number": "0398", "file": "0398 - Constance Prince Maurice - Princely Villa - thatched dining pavilion with stone wall and chandelier.jpg", "resort": "Constance Prince Maurice", "space": "Princely Villa", "description": "The Princely Villa open air dining pavilion, a vast thatched roof on rough timber posts against a dry stone wall, lit by a multi arm chandelier with fabric shades. A long timber dining table set with glassware and a tall floral arrangement faces low grey lounge sofas, with the private pool and sea beyond. Recreate with a stone feature wall, oversized pendant lighting, mixed dining and lounge zones and sand toned upholstery.", "src": "images/Constance Prince Maurice/0398 - Constance Prince Maurice - Princely Villa - thatched dining pavilion with stone wall and chandelier.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1708", "size": 1035646}, {"number": "0458", "file": "0458 - Alila Ubud - Deluxe Room - twin room with garden terrace and outdoor armchairs.jpg", "resort": "Alila Ubud", "space": "Deluxe Room", "description": "Ground floor Deluxe twin room in the village blocks, its beds dressed in white with gold patterned runners, a tall louvred timber wardrobe and vanity to one side. Glass doors open fully to a private garden terrace where timber armchairs and a side table sit on stone paving against a low stone wall and lawn, the first step in the resort's indoor outdoor living pattern that the villas take further.", "src": "images/Alila Ubud/0458 - Alila Ubud - Deluxe Room - twin room with garden terrace and outdoor armchairs.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 338493}, {"number": "0466", "file": "0466 - Alila Ubud - Valley Villa - open bedroom with timber desk, rattan chair and draped canopy bed.jpg", "resort": "Alila Ubud", "space": "Valley Villa", "description": "Valley Villa bedroom photographed from behind its dark timber writing desk, which carries twin shaded lamps and a woven rattan chair. Beyond, the bed is hung with sheer white canopy drapes and faces a full wall of glass over the Ayung valley, with a cushioned window seat built in to one side. The woven thatch ceiling and timber floor keep the open plan room warm despite its size.", "src": "images/Alila Ubud/0466 - Alila Ubud - Valley Villa - open bedroom with timber desk, rattan chair and draped canopy bed.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 446060}];
